/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string }
  | { kind: "file"; file: File; name: string };

/**
 * FEAT-001 (#60): 録音由来の疑似ファイル参照。
 * `kind: "recording"` はディスク上の実ファイルではなく、メモリ上の
 * 録音バッファを表す。`mediaSource.blob` に録音結果が入るので、
 * `LoadedAudio` としては既存経路と同じ振る舞いをする。
 */
export type RecordedAudioRef = {
  kind: "recording";
  /** UI 表示用の仮想ファイル名(例: "録音_20260922_153000.wav")。 */
  name: string;
  /** "loopback" | "microphone" — どこから録ったか。 */
  source: "loopback" | "microphone";
  /** Tauri: appDataDir/recordings/ に保存済みの実ファイルパス(#70)。
   *  ある場合は内容がディスク上に永続化されており、プロジェクトの
   *  sourceAudio(originalPath/contentHash)に載せられる。 */
  path?: string;
  /** path を持つ録音の SHA-256(FND-001 の contentHash 契約)。 */
  contentHash?: string;
  /** ブラウザ dev 等、実ファイルが無い場合の録音バイト列。 */
  blob?: Blob;
};

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef | RecordedAudioRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. */
  | { kind: "projectOpenFailed"; fileName: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
  path: string;
  projectId: string;
  /** Display name — file basename without the .hornscribe.json suffix. */
  name: string;
  sourcePath: string | null;
  sourceHash: string | null;
}

/** SOURCE_MISSING context: which project lost its audio, and whether the
 *  last relink candidate failed the content-hash check (deck:
 *  sourceMoved vs sourceHashMismatch copy). */
export interface SourceMissingInfo {
  project: ProjectSummary;
  mismatch: boolean;
}

/** A "最近使ったプロジェクト" entry (GUI_UX_SPEC §3). */
export interface RecentProjectEntry {
  name: string;
  path: string;
  /** Epoch ms of the last successful open (sorting + pruning). */
  openedAt: number;
}

/**
 * 採譜オプション (GUI_UX_SPEC §4 advanced options — hidden in the popover
 * next to 採譜を開始). Values are option keys; Japanese labels resolve via
 * ja.import.audioOptions. Consumed by the transcription feature (UI-040),
 * persisted nowhere yet.
 */
export interface TranscriptionOptions {
  tempo: "auto" | "manual";
  tempoBpm: number | null;
  meter: string;
  minDuration: string;
  triplets: "auto" | "allow" | "none";
  simplicity: "standard" | "simple" | "detailed";
  range: "all" | "selection";
  /** 範囲指定時の開始/終了（秒）。null = 音声の端まで。 */
  selectionStartSec: number | null;
  selectionEndSec: number | null;
}

export const DEFAULT_TRANSCRIPTION_OPTIONS: TranscriptionOptions = {
  tempo: "auto",
  tempoBpm: null,
  meter: "auto",
  minDuration: "16",
  triplets: "auto",
  simplicity: "standard",
  range: "all",
  selectionStartSec: null,
  selectionEndSec: null,
};

/**
 * Settings persistence (UI-060; GUI_UX_SPEC §18/§26).
 *
 * User-facing settings live in one localStorage record (mirroring the
 * existing `hornscribe.theme` / layout persistence — best-effort, never
 * crashes when storage is unavailable or holds stale/foreign data).
 * Only known keys are merged back and every value is re-validated, so a
 * corrupt or newer-version blob degrades to defaults field by field.
 *
 * NO language setting exists — the UI is Japanese-only by contract.
 */

import { useCallback, useMemo, useState } from "react";

const STORAGE_KEY = "hornscribe.settings";

/** The §18 categories in display order (録音 sits between 再生 and 採譜). */
export const SETTINGS_CATEGORIES = [
  "appearance",
  "playback",
  "recordings",
  "transcription",
  "score",
  "export",
  "tools",
  "advanced",
] as const;

export type SettingsCategory = (typeof SETTINGS_CATEGORIES)[number];

export type TempoMode = "auto" | "manual";
export type MeterSetting = "auto" | "4/4" | "3/4" | "6/8" | "2/4";
export type MinDurationSetting = "eighth" | "sixteenth" | "thirtySecond";
export type ScoreViewMode = "continuous" | "page";
export type BackendSetting = "auto" | "basicPitch";

export interface AppSettings {
  /** 再生 → 標準再生速度 (0.5–2.0). */
  readonly playbackRate: number;
  /** 再生 → 戻る/進む秒数. */
  readonly skipSeconds: number;
  /** 再生 → 再生位置を追従. */
  readonly followPlayback: boolean;
  /** 採譜 → テンポ auto/manual + BPM value. */
  readonly tempoMode: TempoMode;
  readonly bpm: number;
  /** 採譜 → 拍子. */
  readonly meter: MeterSetting;
  /** 採譜 → 最小音価. */
  readonly minDuration: MinDurationSetting;
  /** 採譜 → 三連符を使う. */
  readonly triplets: boolean;
  /** 楽譜 → 初期表示. */
  readonly scoreInitialView: ScoreViewMode;
  /** 書き出し → 既定の保存先 ("" = choose at export time). */
  readonly defaultExportDir: string;
  /** 書き出し → MuseScoreの場所 ("" = auto-detect). */
  readonly museScorePath: string;
  /** ツール → FFmpegの場所 ("" = auto-detect). */
  readonly ffmpegPath: string;
  /** 詳細設定 → 採譜エンジン. */
  readonly backend: BackendSetting;
  /** 録音 → 自動削除の保持日数 (0 = 削除しない). */
  readonly recordingsRetentionDays: number;
}

export const DEFAULT_SETTINGS: AppSettings = {
  playbackRate: 1,
  skipSeconds: 5,
  followPlayback: true,
  tempoMode: "auto",
  bpm: 120,
  meter: "auto",
  minDuration: "sixteenth",
  triplets: true,
  scoreInitialView: "continuous",
  defaultExportDir: "",
  museScorePath: "",
  ffmpegPath: "",
  backend: "auto",
  recordingsRetentionDays: 0,
};

const RATES = [0.5, 0.75, 1, 1.25, 1.5, 2];
const METERS: readonly MeterSetting[] = [
  "auto",
  "4/4",
  "3/4",
  "6/8",
  "2/4",
];
const MIN_DURATIONS: readonly MinDurationSetting[] = [
  "eighth",
  "sixteenth",
  "thirtySecond",
];
const VIEWS: readonly ScoreViewMode[] = ["continuous", "page"];
const BACKENDS: readonly BackendSetting[] = ["auto", "basicPitch"];

function num(v: unknown, min: number, max: number): number | null {
  return typeof v === "number" && Number.isFinite(v) && v >= min && v <= max
    ? v
    : null;
}
function str(v: unknown): string | null {
  return typeof v === "string" ? v : null;
}
function bool(v: unknown): boolean | null {
  return typeof v === "boolean" ? v : null;
}
function oneOf<T extends string>(v: unknown, list: readonly T[]): T | null {
  return typeof v === "string" && (list as readonly string[]).includes(v)
    ? (v as T)
    : null;
}

/** Parse + validate the stored blob; unknown/invalid fields get defaults. */
export function parseSettings(raw: string | null): AppSettings {
  if (!raw) return DEFAULT_SETTINGS;
  let o: Record<string, unknown>;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return DEFAULT_SETTINGS;
    o = parsed as Record<string, unknown>;
  } catch {
    return DEFAULT_SETTINGS;
  }
  const d = DEFAULT_SETTINGS;
  return {
    playbackRate: num(o.playbackRate, 0.25, 4) ?? d.playbackRate,
    skipSeconds: num(o.skipSeconds, 1, 60) ?? d.skipSeconds,
    followPlayback: bool(o.followPlayback) ?? d.followPlayback,
    tempoMode: oneOf(o.tempoMode, ["auto", "manual"]) ?? d.tempoMode,
    bpm: num(o.bpm, 30, 300) ?? d.bpm,
    meter: oneOf(o.meter, METERS) ?? d.meter,
    minDuration: oneOf(o.minDuration, MIN_DURATIONS) ?? d.minDuration,
    triplets: bool(o.triplets) ?? d.triplets,
    scoreInitialView: oneOf(o.scoreInitialView, VIEWS) ?? d.scoreInitialView,
    defaultExportDir: str(o.defaultExportDir) ?? d.defaultExportDir,
    museScorePath: str(o.museScorePath) ?? d.museScorePath,
    ffmpegPath: str(o.ffmpegPath) ?? d.ffmpegPath,
    backend: oneOf(o.backend, BACKENDS) ?? d.backend,
    recordingsRetentionDays:
      num(o.recordingsRetentionDays, 0, 3650) ?? d.recordingsRetentionDays,
  };
}

export function loadSettings(): AppSettings {
  try {
    return parseSettings(window.localStorage.getItem(STORAGE_KEY));
  } catch {
    return DEFAULT_SETTINGS;
  }
}

export function saveSettings(settings: AppSettings): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    /* persistence is best-effort — the session keeps working */
  }
}

/** Valid playback-rate options surfaced in 設定 → 再生. */
export function playbackRateOptions(): readonly number[] {
  return RATES;
}

/**
 * React binding: current settings + a merge-style updater that persists
 * immediately (the theme switcher sets the precedent — changes apply at
 * once, no save button).
 */
export function useAppSettings(): {
  settings: AppSettings;
  update: (patch: Partial<AppSettings>) => void;
} {
  const [settings, setSettings] = useState<AppSettings>(loadSettings);
  const update = useCallback((patch: Partial<AppSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      saveSettings(next);
      return next;
    });
  }, []);
  return useMemo(() => ({ settings, update }), [settings, update]);
}
